/* ══════════════════════════════════════════════════════════════════════════
   MOTOR
   ══════════════════════════════════════════════════════════════════════════ */

const LETRAS = 'A-Za-zÁÉÍÓÚÜÑáéíóúüñ';
const RE_PALABRA = new RegExp('[' + LETRAS + ']+', 'g');
const RE_SOLO_LETRAS = new RegExp('^[' + LETRAS + ']+$');

const norm = (s: string) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const tieneTilde = (s: string) => /[áéíóúüñÁÉÍÓÚÜÑ]/.test(s);

/* Clave fonética: agrupa las confusiones típicas del español escrito
   (b/v, c/s/z, ll/y, g/j, h muda, qu/k/c, x/cs, nb/mb, letras dobles). */
function fon(w: string): string {
  let s = norm(w).replace(/[^a-z]/g, '');
  s = s.replace(/ch/g, '#');
  s = s.replace(/qu(?=[ei])/g, 'k').replace(/q/g, 'k');
  s = s.replace(/gu(?=[ei])/g, 'G');
  s = s.replace(/g(?=[ei])/g, 'j').replace(/G/g, 'g');
  s = s.replace(/c(?=[ei])/g, 's').replace(/c/g, 'k');
  s = s.replace(/z/g, 's').replace(/x/g, 'ks').replace(/h/g, '').replace(/v/g, 'b').replace(/w/g, 'b').replace(/ll/g, 'y');
  s = s.replace(/y$/, 'i').replace(/nb/g, 'mb').replace(/np/g, 'mp');
  s = s.replace(/rr/g, 'R');
  s = s.replace(/(.)\1+/g, '$1');
  return s.replace(/#/g, 'ch').replace(/R/g, 'rr');
}

/* ── Índices (se construyen una sola vez, la primera vez que se corrige) ── */
let LEX: Map<string, number> | null = null;   // palabra válida → frecuencia (cB: menor = más usada)
let NODEST: Set<string> | null = null;       // válidas pero nunca usadas como corrección (extranjerismos)
let ERR: Map<string, string> | null = null;   // error → corrección
let POR_NORM: Map<string, string[]> | null = null;
let POR_FON: Map<string, string[]> | null = null;
let PART: Set<string> | null = null;          // participios (-ado/-ido + irregulares)
let PRET: Map<string, string> | null = null;  // cobro → cobró (formas en -o con pretérito -ó)

function init() {
  if (LEX) return;
  LEX = new Map();
  for (const linea of LEXICO_TXT.split('\n')) {
    const i = linea.indexOf(':');
    if (i < 0) continue;
    const cb = +linea.slice(0, i);
    for (const w of linea.slice(i + 1).split(' ')) if (w) LEX.set(w, cb);
  }
  NODEST = new Set(NO_DESTINO_TXT.split(/\s+/).filter(Boolean));
  ERR = new Map();
  for (const par of ERRORES_TXT.split(/\s+/)) {
    const i = par.indexOf('>');
    if (i > 0) ERR.set(par.slice(0, i), par.slice(i + 1).replace(/_/g, ' '));
  }
  POR_NORM = new Map();
  POR_FON = new Map();
  PART = new Set(IRREGULARES_PART);
  PRET = new Map();
  for (const [w, cb] of LEX) {
    if (tieneTilde(w)) {                                   // solo las que llevan tilde/ñ: el resto se encuentra directo
      const n = norm(w);
      const a = POR_NORM.get(n); if (a) a.push(w); else POR_NORM.set(n, [w]);
    }
    if (cb > 660 || NODEST.has(w)) continue;               // índice fonético solo con palabras de uso real
    const f = fon(w);
    const b = POR_FON.get(f); if (b) b.push(w); else POR_FON.set(f, [w]);
    if (/(ado|ido|ído)$/.test(w)) {
      const base = w.replace(/(ado|ido|ído)$/, '');
      if (/ado$/.test(w) ? LEX.has(base + 'ar') : (LEX.has(base + 'er') || LEX.has(base + 'ir') || LEX.has(base + 'ír'))) PART.add(w);
    }
    if (w.endsWith('o') && !tieneTilde(w)) {
      const p = w.slice(0, -1) + 'ó';
      if (LEX.has(p) && LEX.has(w.slice(0, -1) + 'ar')) PRET.set(w, p);
    }
  }
}

const cbDe = (w: string) => (LEX as Map<string, number>).get(w) ?? 999;
const esValida = (w: string) => (LEX as Map<string, number>).has(w);
const esDestino = (w: string) => esValida(w) && !(NODEST as Set<string>).has(w);

/* Elige el candidato más usado si se distingue claramente del segundo. */
function elige(cands: Iterable<string>, margen: number, maxCb: number): string | null {
  const l = [...new Set(cands)].filter(esDestino).sort((a, b) => cbDe(a) - cbDe(b));
  if (!l.length || cbDe(l[0]) > maxCb) return null;
  if (l.length > 1 && cbDe(l[1]) - cbDe(l[0]) < margen) return null;
  return l[0];
}

const ALFABETO = 'abcdefghijklmnñopqrstuvwxyzáéíóú';
function ediciones1(w: string): Set<string> {
  const out = new Set<string>();
  for (let i = 0; i <= w.length; i++) {
    const a = w.slice(0, i), b = w.slice(i);
    if (b) out.add(a + b.slice(1));                                  // sobra una letra
    if (b.length > 1) out.add(a + b[1] + b[0] + b.slice(2));          // letras invertidas
    for (const c of ALFABETO) {
      if (b) out.add(a + c + b.slice(1));                              // letra equivocada
      out.add(a + c + b);                                              // falta una letra
    }
  }
  out.delete(w);
  return out;
}

const FUNC = new Set(['a', 'y', 'o', 'e', 'u', 'de', 'del', 'el', 'la', 'lo', 'los', 'las', 'le', 'les', 'en', 'un', 'una',
  'unos', 'unas', 'se', 'su', 'sus', 'al', 'mi', 'mis', 'tu', 'me', 'te', 'nos', 'no', 'ni', 'ya', 'es', 'si', 'yo', 'ha',
  'he', 'han', 'va', 'que', 'por', 'para', 'con', 'sin', 'muy', 'mas', 'más', 'hay', 'fue', 'son', 'era', 'este', 'esta',
  'ese', 'esa', 'pero', 'como', 'cuando', 'porque', 'sobre', 'entre', 'desde', 'hasta']);
/* Forma válida de una pieza (directa o corrigiendo un error conocido: electronica → electrónica). */
function formaPieza(w: string, max = 620): string | null {
  if (w.length <= 2) return FUNC.has(w) ? w : null;
  if (esDestino(w) && cbDe(w) <= max) return w;
  const e = (ERR as Map<string, string>).get(w);
  if (e && !e.includes(' ') && esDestino(e) && cbDe(e) <= max) return e;
  return null;
}
const parteBuena = (w: string, max = 620) => formaPieza(w, max) !== null;

/* «delcliente» → «del cliente»; «sinembargo» → «sin embargo». Hasta 3 piezas. */
function separa(w: string, prof = 0, soloFunc = false): string[] | null {
  let mejor: string[] | null = null, mejorCb = 1e9;
  for (let i = 1; i < w.length; i++) {
    const a = w.slice(0, i), b = w.slice(i);
    if (!parteBuena(a)) continue;
    let resto: string[] | null = null;
    if (parteBuena(b)) resto = [b];
    else if (prof < 1 && b.length >= 4) resto = separa(b, prof + 1, soloFunc);
    if (!resto) continue;
    const piezas = [formaPieza(a) as string, ...resto.map(r => formaPieza(r) ?? r)];
    if (soloFunc && !piezas.some(p => FUNC.has(p))) continue;
    if (piezas.filter(p => p.length === 1).length > 1) continue;
    const peor = Math.max(...piezas.map(cbDe)) + piezas.length * 40;
    if (peor < mejorCb) { mejorCb = peor; mejor = piezas; }
  }
  return mejor;
}

function aplicaCaso(original: string, rep: string): string {
  if (original.length > 1 && original === original.toUpperCase()) return rep.toUpperCase();
  if (original[0] !== original[0].toLowerCase()) return rep[0].toUpperCase() + rep.slice(1);
  return rep;
}

/* Si el usuario escribió una tilde («yegó») y la corrección no la trae
   («llego»), se traslada a la misma vocal contando desde el final («llegó»). */
const CON_ACENTO: Record<string, string> = { a: 'á', e: 'é', i: 'í', o: 'ó', u: 'ú' };
function conservaTilde(tok: string, rep: string): string {
  if (!tieneTilde(tok) || tieneTilde(rep) || rep.includes(' ')) return rep;
  const t = tok.toLowerCase();
  for (let i = 1; i <= t.length && i <= rep.length; i++) {
    const c = t[t.length - i], base = norm(c);
    if (c !== base && CON_ACENTO[base] && rep[rep.length - i] === base) {
      const cand = rep.slice(0, rep.length - i) + CON_ACENTO[base] + rep.slice(rep.length - i + 1);
      return esValida(cand) ? cand : rep;
    }
  }
  return rep;
}

const EXCEPCIONES_ION = new Set(['guion', 'ion', 'prion', 'pion', 'muon', 'gorrion', 'truhan']);

/* Corrige una palabra suelta. `inicio` = es la primera palabra de una oración. */
function corrigePalabra(tok: string, inicio: boolean): string {
  if (tok.length < 2 && !(ERR as Map<string, string>).has(tok.toLowerCase())) return tok;
  if (tok.length > 1 && tok === tok.toUpperCase()) return tok;                 // siglas: SAC, PQRS, ESSA
  if (/[A-ZÁÉÍÓÚÑ]/.test(tok.slice(1))) return tok;                            // PowerApps, McDonald
  const low = tok.toLowerCase();
  const minus = tok === low;
  const k = norm(low);
  const E = ERR as Map<string, string>;

  if (tieneTilde(low) && esValida(low)) return tok;                             // «dañó», «está»: se respetan
  // En nombres propios (mayúscula a mitad de oración) solo se corrigen tildes: Garcia → García.
  const soloTildes = !minus && !inicio;
  const vale = (rep: string) => !soloTildes || (norm(rep) === k && !/ñ/.test(rep) === !/ñ/.test(low));
  const e0 = E.get(low) ?? (esValida(low) ? undefined : E.get(k));
  if (esValida(low) && !E.has(low)) return tok;
  if (e0 !== undefined) return vale(e0) ? aplicaCaso(tok, conservaTilde(tok, e0)) : tok;

  // 1. Misma palabra con tildes distintas o faltantes (también en nombres: Bogota → Bogotá).
  const misma = POR_NORM?.get(k);
  if (misma) {
    const c = elige(misma, 60, 760);
    if (c && vale(c)) return aplicaCaso(tok, c);
  }
  const libre = minus || inicio;                 // a nombres propios no se les adivina la palabra
  const maxCb = minus ? 640 : 560;

  // Letras repetidas: «holaaa», «carrro».
  if (/(.)\1\1/.test(low)) {
    const r2 = low.replace(/(.)\1{2,}/g, '$1$1'), r1 = low.replace(/(.)\1{2,}/g, '$1');
    const c2 = esDestino(r2) ? r2 : esDestino(r1) ? r1 : null;
    if (c2) return aplicaCaso(tok, c2);
  }
  const sufijoTilde = /[cs]ión(es)?$|[aeiou]ción$/.test(low);
  // 2. Unión evidente con palabra corta: «dela» → «de la», «alos» → «a los».
  if (libre && low.length >= 3 && !sufijoTilde) {
    const p = separa(low, 0, true);
    if (p && p.some(x => x.length <= 3 && FUNC.has(x)) && p.every(x => x.length <= 2 || cbDe(x) <= 560)) return aplicaCaso(tok, p.join(' '));
  }

  if (libre && !tieneTilde(low) && low.length >= 3) {
    // 3. Misma pronunciación: bisita → visita, resivimos → recibimos, yamada → llamada.
    const f = fon(low);
    const c = elige(POR_FON?.get(f) ?? [], 50, maxCb);
    if (c) return aplicaCaso(tok, c);

  }

  if (libre && low.length >= 4 && !sufijoTilde) {
    // 5. Error de tecleo: una letra de más, de menos, cambiada o invertida.
    const e1 = [...ediciones1(low)].filter(esDestino);
    let c = e1.length ? elige(e1, 50, maxCb - 20) : null;
    // 6. Tecleo + confusión fonética a la vez (una edición sobre la clave fonética).
    if (!c && !e1.length && low.length >= 5 && !tieneTilde(low)) {
      const cands: string[] = [];
      for (const v of ediciones1(fon(low))) { const l = POR_FON?.get(v); if (l) cands.push(...l); }
      c = elige(cands, 70, maxCb - 40);
    }
    if (c) return aplicaCaso(tok, conservaTilde(tok, c));
  }

  // 7. Palabras pegadas sin palabra corta: «facturaelectronica».
  if (libre && low.length >= 7 && !tieneTilde(low)) {
    const p = separa(low);
    if (p && p.length === 2 && p.every(x => x.length >= 3)) return aplicaCaso(tok, p.join(' '));
  }

  // 8. Terminaciones que siempre llevan tilde.
  if (!tieneTilde(tok) && tok.length >= 5) {
    if (/cion$/.test(k)) return aplicaCaso(tok, k.slice(0, -4) + 'ción');
    if (/sion$/.test(k)) return aplicaCaso(tok, k.slice(0, -4) + 'sión');
    if (/ion$/.test(k) && !EXCEPCIONES_ION.has(k)) return aplicaCaso(tok, k.slice(0, -3) + 'ión');
  }
  return tok;
}

/* ── Correos electrónicos ─────────────────────────────────────────────── */
const PROVEEDORES = ['gmail', 'hotmail', 'outlook', 'yahoo', 'icloud', 'live', 'msn', 'aol', 'protonmail', 'essa', 'epm',
  'une', 'etb', 'claro', 'tigo', 'movistar', 'unal', 'uis', 'unab', 'udes', 'santander', 'bancolombia'];
const PROV_LARGOS = ['gmail', 'hotmail', 'outlook', 'yahoo', 'icloud', 'protonmail'];
const ALIAS_PROV: Record<string, string> = {
  gemail: 'gmail', gmali: 'gmail', gmial: 'gmail', gamil: 'gmail', gmal: 'gmail', gmai: 'gmail', gmil: 'gmail', gnail: 'gmail',
  gmeil: 'gmail', gmaail: 'gmail', gmaill: 'gmail', jmail: 'gmail', gimail: 'gmail', gmsil: 'gmail', gmaik: 'gmail', gmaul: 'gmail',
  hotmial: 'hotmail', hotmal: 'hotmail', hotmai: 'hotmail', hotmil: 'hotmail', homail: 'hotmail', hotamil: 'hotmail', hormail: 'hotmail',
  hotmeil: 'hotmail', jotmail: 'hotmail', otmail: 'hotmail', hotmaill: 'hotmail', hotnail: 'hotmail', hitmail: 'hotmail', hotmsil: 'hotmail',
  hotmaik: 'hotmail', homtail: 'hotmail', hptmail: 'hotmail', hoymail: 'hotmail', outlok: 'outlook', outllok: 'outlook', otlook: 'outlook',
  outook: 'outlook', outloock: 'outlook', autlook: 'outlook', oulook: 'outlook', outluk: 'outlook', outlool: 'outlook', outlokk: 'outlook',
  yaho: 'yahoo', yahooo: 'yahoo', yhoo: 'yahoo', yahho: 'yahoo', yaoo: 'yahoo', yajoo: 'yahoo', yahooe: 'yahoo', yaboo: 'yahoo',
  iclod: 'icloud', iclou: 'icloud', icoud: 'icloud', icluod: 'icloud', icload: 'icloud',
};
const TLD_MAL: Record<string, string> = {
  con: 'com', cmo: 'com', ocm: 'com', comm: 'com', cm: 'com', om: 'com', vom: 'com', xom: 'com', coml: 'com', cim: 'com', cpm: 'com',
  cpom: 'com', comn: 'com', clm: 'com', coom: 'com', ccom: 'com', comk: 'com', co: 'com', con_: 'com',
};
function distancia(a: string, b: string): number {
  const d: number[][] = [];
  for (let i = 0; i <= a.length; i++) { d[i] = [i]; }
  for (let j = 0; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
  }
  return d[a.length][b.length];
}
function arreglaProveedor(p: string): string {
  const l = p.toLowerCase().replace(/-/g, '');
  if (PROVEEDORES.includes(l)) return l;
  if (ALIAS_PROV[l]) return ALIAS_PROV[l];
  const cerca = PROV_LARGOS.filter(x => distancia(l, x) <= (x.length >= 6 ? 2 : 1));
  return cerca.length === 1 ? cerca[0] : p;
}
/** Corrige el dominio de los correos: «juan@gamil.con» → «juan@gmail.com»,
 *  «ana @ hotmial . com» → «ana@hotmail.com», «pedro@gmail» → «pedro@gmail.com». */
export function corregirCorreos(texto: string): string {
  if (!texto || !texto.includes('@')) return texto;
  return texto.replace(/([A-Za-z0-9._%+-]+)[ \t]*@[ \t]*([A-Za-z0-9-]+(?:[ \t]*\.[ \t]*[A-Za-z]{2,5}){0,3})/g, (_m, usuario: string, dom: string) => {
    let partes = dom.replace(/[ \t]+/g, '').split('.');
    // «gmailcom» → «gmail» + «com»
    if (partes.length === 1) {
      const m = /^(.+?)(com|co|es|net)$/i.exec(partes[0]);
      if (m && PROVEEDORES.includes(arreglaProveedor(m[1]))) partes = [m[1], m[2]];
    }
    partes[0] = arreglaProveedor(partes[0]);
    const prov = partes[0].toLowerCase();
    if (PROV_LARGOS.includes(prov) || prov === 'live' || prov === 'msn') {
      if (partes.length === 1) partes.push('com');
      const t = partes[1].toLowerCase();
      if (TLD_MAL[t] && !(t === 'co' && partes.length > 2)) partes[1] = TLD_MAL[t];
      if (prov === 'gmail' || prov === 'icloud') partes = [prov, 'com'];
    } else if (partes.length > 1 && TLD_MAL[partes[1].toLowerCase()] && !['co', 'cm', 'om'].includes(partes[1].toLowerCase())) {
      partes[1] = 'com';                                   // atencion@essa.con.co → atencion@essa.com.co
    }
    return usuario + '@' + partes.join('.');
  });
}

/* ── Espacios y puntuación ────────────────────────────────────────────── */
function corrigeEspacios(t: string): string {
  return t
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[ \t]+([,.;:!?)\]])/g, '$1')
    .replace(/([(¿¡])[ \t]+/g, '$1')
    .replace(new RegExp('([' + LETRAS + '])([,;:])(?=[' + LETRAS + '])', 'g'), '$1$2 ')
    .replace(new RegExp('([a-záéíóúüñ]{2})([.!?])(?=[A-ZÁÉÍÓÚÑ][a-záéíóúüñ])', 'g'), '$1$2 ');
}
const RE_ABREV = /\b(etc|sr|sra|srs|sres|dr|dra|no|n|núm|num|nro|cra|cr|cl|cll|av|kr|mz|apto|ing|lic|aprox|vda|tel|cel|art|inc|lit|pág|pag|ej|esq|of|ud|uds|cc|nit)\.\s+$/i;
function mayusculas(t: string): string {
  return t.replace(/([.!?]\s+|\n\s*)([¿¡]?)([a-záéíóúüñ])/g, (m0: string, a: string, q: string, b: string, pos: number) =>
    RE_ABREV.test(t.slice(Math.max(0, pos - 12), pos + a.length)) ? m0 : a + q + b.toUpperCase());
}

/* ── Gramática frecuente ──────────────────────────────────────────────── */
type Tok = { w: string; sep: string };   // sep = texto que va ANTES de la palabra

const AUX: Record<string, string> = { a: 'ha', e: 'he', as: 'has', an: 'han', emos: 'hemos', abia: 'había', abian: 'habían' };
const PREV_E = new Set(['yo', 'ya', 'no', 'lo', 'la', 'le', 'les', 'los', 'las', 'me', 'te', 'se', 'nos', 'nunca', 'siempre', 'también', 'aún', 'todavía']);
const SUJ3 = new Set(['usuario', 'usuaria', 'cliente', 'técnico', 'técnica', 'funcionario', 'funcionaria', 'empresa', 'operario',
  'contratista', 'señor', 'señora', 'él', 'ella', 'usted', 'essa', 'electrificadora', 'personal', 'cuadrilla', 'entidad', 'quien',
  'propietario', 'propietaria', 'arrendatario', 'arrendataria', 'suscriptor', 'suscriptora', 'peticionario', 'peticionaria',
  'solicitante', 'ciudadano', 'ciudadana', 'inquilino', 'inquilina', 'administrador', 'administradora', 'lector', 'asesor', 'asesora',
  'compañía', 'brigada', 'ingeniero', 'ingeniera', 'electricista', 'vecino', 'vecina', 'esposo', 'esposa', 'hijo', 'hija', 'medidor',
  'contador', 'transformador', 'sistema', 'servicio', 'luz', 'energía', 'factura', 'recibo']);
const NOMBRE_O = new Set(['cambio', 'pago', 'cobro', 'reclamo', 'retiro', 'registro', 'aumento', 'consumo', 'uso', 'envio', 'reporto_x', 'trabajo', 'aviso', 'cargo', 'abono', 'cobro', 'giro', 'paso', 'corto', 'daño', 'informo_x']);
const TRAS_ESTA = new Set(['en', 'bien', 'mal', 'muy', 'sin', 'pendiente', 'pendientes', 'cerca', 'lejos', 'aquí', 'ahí', 'allí',
  'listo', 'lista', 'listos', 'listas', 'mejor', 'peor', 'claro', 'seguro', 'segura', 'vigente', 'vencido', 'vencida', 'suspendido',
  'suspendida', 'activo', 'activa', 'quemado', 'quemada', 'dañado', 'dañada', 'apagado', 'apagada', 'caído', 'caída', 'desconectado',
  'conectado', 'funcionando', 'inclinado', 'inclinada', 'roto', 'rota', 'abierto', 'abierta', 'al', 'a', 'de', 'por', 'para', 'como', 'todavía', 'aún', 'ya', 'siendo']);
const TRAS_SE_SABER = new Set(['porque', 'si', 'cómo', 'como', 'cuándo', 'cuando', 'dónde', 'donde', 'nada', 'cuál', 'cual', 'quién', 'quien', 'qué', 'cuánto', 'cuanto']);
const INTERROG: Record<string, string> = { que: 'qué', como: 'cómo', cuando: 'cuándo', donde: 'dónde', adonde: 'adónde', quien: 'quién',
  quienes: 'quiénes', cual: 'cuál', cuales: 'cuáles', cuanto: 'cuánto', cuanta: 'cuánta', cuantos: 'cuántos', cuantas: 'cuántas' };
const PIDE_PORQUE = new Set(['sé', 'entiendo', 'entendemos', 'entienden', 'saber', 'sabemos', 'saben', 'sabe', 'explique', 'expliquen',
  'explicar', 'explica', 'explican', 'indique', 'indiquen', 'informe', 'informen', 'aclare', 'aclaren', 'pregunto', 'preguntamos',
  'preguntar', 'comprendo', 'comprendemos', 'desconozco', 'desconocemos', 'motivo', 'razón']);
const SABER = new Set(['sé', 'saber', 'sabemos', 'saben', 'sabe', 'pregunto', 'preguntamos', 'preguntar', 'explique', 'expliquen', 'explicar', 'entiendo', 'entendemos', 'desconozco', 'desconocemos', 'averiguar', 'consultar']);
const NO_DEL = new Set(['que', 'cual', 'mismo', 'misma', 'es', 'era', 'fue', 'tiene', 'tenía', 'dijo', 'dice', 'sí', 'solo', 'también',
  'no', 'le', 'lo', 'la', 'se', 'me', 'nos', 'ha', 'había', 'hizo', 'puede', 'pudo', 'quiere', 'está', 'estaba', 'sabe', 'va']);
const VEZ_PREV = new Set(['una', 'otra', 'cada', 'tal', 'la', 'esta', 'primera', 'segunda', 'tercera', 'última', 'alguna', 'ninguna', 'aquella', 'esa']);
const MAS_SIG = new Set(['de', 'del', 'que', 'alto', 'alta', 'altos', 'altas', 'caro', 'cara', 'elevado', 'elevada', 'tiempo', 'bien',
  'tarde', 'pronto', 'rápido', 'grande', 'bajo', 'baja', 'información', 'dinero', 'veces', 'claro', 'clara', 'días', 'meses', 'barato',
  'barata', 'costoso', 'costosa', 'consumo', 'cobros', 'problemas', 'o', 'allá', 'adelante', 'tardar', 'fácil', 'difícil', 'grave', 'urgente']);
const MAS_PREV = new Set(['lo', 'es', 'los', 'las', 'el', 'la', 'cada', 'mucho', 'mucha', 'poco', 'nada', 'algo', 'aún', 'todavía', 'vez', 'cobran', 'pagar', 'pago', 'cobrar', 'mucho']);
const HABIAN_SIG = new Set(['muchos', 'muchas', 'varios', 'varias', 'unos', 'unas', 'demasiados', 'demasiadas', 'algunos', 'algunas',
  'dos', 'tres', 'problemas', 'personas', 'cables', 'postes', 'árboles', 'ramas', 'daños', 'cortes', 'fallas']);
const IRREGULARES_PART = ['sido', 'hecho', 'dicho', 'puesto', 'visto', 'vuelto', 'escrito', 'roto', 'abierto', 'resuelto', 'devuelto',
  'cubierto', 'descubierto', 'muerto', 'impreso', 'satisfecho', 'propuesto', 'dispuesto', 'compuesto', 'supuesto', 'repuesto',
  'expuesto', 'impuesto', 'descrito', 'inscrito', 'suscrito', 'prescrito', 'previsto', 'revisto', 'deshecho', 'envuelto', 'frito'];

function corrigeGramatica(T: Tok[]): void {
  const lw = (i: number) => (i >= 0 && i < T.length ? T[i].w.toLowerCase() : '');
  const junto = (i: number) => i > 0 && i < T.length && /^[ \t]+$/.test(T[i].sep);             // separado del anterior solo por espacios
  const set = (i: number, v: string) => { T[i].w = aplicaCaso(T[i].w, v); };
  const P = PART as Set<string>;
  const esPart = (w: string) => P.has(w);
  const esPart2 = (w: string) => esPart(w) || (/(ad|id)(a|os|as)$/.test(w) && esPart(w.replace(/(a|os|as)$/, 'o')));
  const esGer = (w: string) => /(ando|iendo|yendo)$/.test(w) && esValida(w);

  for (let i = 0; i < T.length; i++) {
    const w = lw(i), sig = junto(i + 1) ? lw(i + 1) : '', ant = junto(i) ? lw(i - 1) : '';
    const sig2 = sig && junto(i + 2) ? lw(i + 2) : '';

    // Palabra repetida: «el el cliente» → «el cliente».
    if (sig && sig === w && !['no', 'si', 'sí', 'muy', 'ya'].includes(w)) {
      T.splice(i + 1, 1); i--; continue;
    }
    // a / e / an … + participio → ha / he / han (no en «a pedido de»).
    if (AUX[w] && sig && esPart(sig) && !['de', 'del', 'por'].includes(sig2)) {
      if (w !== 'e' || !ant || PREV_E.has(ant) || !junto(i)) set(i, AUX[w]);
    }
    // «a echo» / «ha echo» → «ha hecho».
    if (w === 'echo' && ['ha', 'he', 'has', 'han', 'hemos', 'haber', 'había', 'habían', 'a', 'e', 'an'].includes(ant)) {
      set(i, 'hecho'); if (AUX[ant]) set(i - 1, AUX[ant]);
    }
    // «haber si» → «a ver si»; «a ver» + participio → «haber».
    if (w === 'haber' && sig === 'si') set(i, 'a ver');
    if (w === 'a' && sig === 'ver' && sig2 && esPart(sig2)) { set(i, 'haber'); T.splice(i + 1, 1); continue; }
    // «ay que» → «hay que».
    if (w === 'ay' && ['que', 'un', 'una', 'unos', 'unas', 'mucho', 'mucha', 'muchos', 'muchas', 'varios', 'varias', 'problemas', 'personas', 'gente'].includes(sig)) set(i, 'hay');
    // «esta dañado» → «está dañado».
    const TRAS_ESTE = ['en', 'bien', 'mal', 'listo', 'lista', 'pendiente', 'muy', 'siendo'];
    if (['esta', 'estas', 'este'].includes(w) && sig && (esPart2(sig) || esGer(sig) || (w === 'esta' ? TRAS_ESTA.has(sig) : TRAS_ESTE.includes(sig)))) {
      set(i, w === 'esta' ? 'está' : w === 'estas' ? 'estás' : 'esté');
    }
    // «se cobro» / «el usuario pago» → «se cobró» / «el usuario pagó».
    if ((PRET as Map<string, string>).has(w) && (ant === 'se' || (SUJ3.has(ant) && !NOMBRE_O.has(w)))) set(i, (PRET as Map<string, string>).get(w) as string);
    // «no se si» → «no sé si».
    if (w === 'se' && ant === 'no' && TRAS_SE_SABER.has(sig)) set(i, 'sé');
    // Interrogativos tras «¿»: «¿como …?» → «¿cómo …?», «¿porque» → «¿por qué».
    if (/¿\s*$/.test(T[i].sep)) {
      if (w === 'porque') set(i, 'por qué');
      else if (w === 'por' && sig === 'que') { set(i + 1, 'qué'); }
      else if (INTERROG[w]) set(i, INTERROG[w]);
    }
    // «no entiendo porque» → «no entiendo por qué»; «el porque» → «el porqué».
    if (w === 'porque' && PIDE_PORQUE.has(ant)) set(i, 'por qué');
    if (w === 'porque' && ['el', 'un', 'su'].includes(ant)) set(i, 'porqué');
    // «e» usada como «y»: «mi hermano e yo» → «mi hermano y yo».
    if (w === 'e' && sig && !/^h?[ií]/.test(sig) && !esPart(sig) && T[i].w === 'e') set(i, 'y');
    // «ola,» al saludar → «hola,».
    if (w === 'ola' && (i === 0 || /[.!?\n¡]\s*$/.test(T[i].sep)) && (i + 1 >= T.length || /^\s*[,!.]/.test(T[i + 1].sep))) set(i, 'hola');
    // Pronombre «él»: «a el le informaron» → «a él le informaron».
    if (w === 'el' && T[i].w === 'el' && ['a', 'de', 'para', 'por', 'con', 'sin', 'entre', 'según', 'que', 'y'].includes(ant) && ['le', 'les', 'lo', 'la', 'los', 'las', 'se', 'me', 'nos', 'no', 'también', 'mismo', 'misma', 'sí', 'solo'].includes(sig)) set(i, 'él');
    // «a cerca de» → «acerca de»; «a parte de» → «aparte de».
    if (w === 'a' && sig === 'cerca' && sig2 === 'de' && !['muy', 'más', 'tan'].includes(ant)) { set(i, 'acerca'); T.splice(i + 1, 1); continue; }
    if (w === 'a' && sig === 'parte' && (sig2 === 'de' || sig2 === 'del')) { set(i, 'aparte'); T.splice(i + 1, 1); continue; }
    // «saber cuanto» → «saber cuánto».
    if (SABER.has(ant) && INTERROG[w] && w !== 'que') set(i, INTERROG[w]);
    // y → e ante i/hi; o → u ante o/ho.
    if (w === 'y' && sig && /^h?i/.test(sig) && !/^hi[aeiou]/.test(sig)) set(i, 'e');
    if (w === 'o' && sig && /^h?[oó]/.test(sig)) set(i, 'u');
    // «de el usuario» → «del usuario»; «a el» → «al».
    if ((w === 'de' || w === 'a') && sig === 'el' && sig2 && sig2.length >= 3 && !NO_DEL.has(sig2) && T[i + 1].w === 'el') {
      set(i, w === 'de' ? 'del' : 'al'); T.splice(i + 1, 1);
    }
    // «una ves» → «una vez».
    if (w === 'ves' && VEZ_PREV.has(ant)) set(i, 'vez');
    // «mas de», «lo mas» → «más».
    if (w === 'mas' && (MAS_SIG.has(sig) || MAS_PREV.has(ant))) set(i, 'más');
    // «hubieron problemas» → «hubo problemas»; «habían muchos» → «había muchos».
    if (w === 'hubieron' && sig && !esPart(sig)) set(i, 'hubo');
    if (w === 'habían' && HABIAN_SIG.has(sig)) set(i, 'había');
    if (w === 'habrán' && HABIAN_SIG.has(sig)) set(i, 'habrá');
    // «que valla a» → «que vaya a».
    if (w === 'valla' && ['a', 'al', 'usted', 'el', 'la', 'alguien'].includes(sig) && ['que', 'se', 'lo', 'le', 'no', 'ojalá'].includes(ant)) set(i, 'vaya');
  }
}

/* ── Palabras partidas o con letras corridas ──────────────────────────── */
const conocida = (w: string) => esValida(w) || (ERR as Map<string, string>).has(w) || (ERR as Map<string, string>).has(norm(w));
const pieza = (w: string) => w.length === 1 ? 'ayoeu'.includes(w) : (w.length === 2 ? FUNC.has(w) || (esDestino(w) && cbDe(w) <= 450) : esDestino(w) && cbDe(w) <= 650);

/* «porqu edecidimos» → «porque decidimos»; «de lcliente» → «del cliente»;
   «un afactura» → «una factura»; «solici tud» → «solicitud». */
let colaTxt = '';
function corrigeLimites(T: Tok[]): void {
  for (let i = 0; i + 1 < T.length; i++) {
    if (!/^[ \t]+$/.test(T[i + 1].sep)) continue;
    const A = T[i].w, B = T[i + 1].w;
    if (B !== B.toLowerCase() || /[A-ZÁÉÍÓÚÑ]/.test(A.slice(1))) continue;
    const a = A.toLowerCase(), b = B;
    if (conocida(a) && conocida(b)) continue;
    const tras = i + 2 < T.length ? T[i + 2].sep : colaTxt;
    if (/^\./.test(tras)) continue;                      // abreviatura: «cra.», «no.»
    const unaConocida = conocida(a) || conocida(b);
    // No se le quitan letras a una palabra correcta si la otra se arregla sola («se ba cada» → «se va cada»).
    const quitarA = !conocida(a), quitarB = !conocida(b);   // a una palabra correcta nunca se le quitan letras
    const opciones: [string, string | null, number][] = [];
    for (let k = 1; k <= 2; k++) {
      if (a.length > k && quitarA) opciones.push([a.slice(0, -k), a.slice(-k) + b, k]);
      if (b.length > k && quitarB) opciones.push([a + b.slice(0, k), b.slice(k), k]);
    }
    opciones.push([a + b, null, 0]);
    let mejor: [string, string | null] | null = null, mejorCb = 1e9;
    for (const [x, y, k] of opciones) {
      const ok = y === null ? (esDestino(x) && cbDe(x) <= (unaConocida ? 540 : 620) && x.length >= 4) : pieza(x) && pieza(y);
      if (!ok) continue;
      const s = Math.max(cbDe(x), y ? cbDe(y) : 0) + k * 15;
      if (s < mejorCb) { mejorCb = s; mejor = [x, y]; }
    }
    if (!mejor) continue;
    T[i].w = aplicaCaso(A, mejor[0]);
    if (mejor[1] === null) T.splice(i + 1, 1); else T[i + 1].w = mejor[1];
  }
}

/* ── Protección de cifras, correos, enlaces y marcadores ──────────────── */
const RE_PROTEGE = /(?:https?:\/\/|www\.)\S+|[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+|\S*[\d_@#\\/|<>{}\[\]=*~^$%&]\S*|[\u0000-\u0008\u000E-\u001F\uE000-\uF8FF⟦⟧«»]/g;

const MEMO = new Map<string, string>();

/** Corrige ortografía, tildes, palabras pegadas o partidas, errores de tecleo,
 *  correos y gramática frecuente. Respeta cifras, radicados, correos y enlaces. */
export function corregirOrtografia(texto: string): string {
  if (!texto) return texto;
  init();
  let t = corregirCorreos(texto);

  // Protege lo que no es texto corriente.
  const guardados: string[] = [];
  t = t.replace(RE_PROTEGE, m => { guardados.push(m); return '\uE000' + (guardados.length - 1) + '\uE001'; });
  t = corrigeEspacios(t);

  // Tokeniza: palabra + separador previo.
  const T: Tok[] = [];
  let ultimo = 0, m: RegExpExecArray | null;
  RE_PALABRA.lastIndex = 0;
  while ((m = RE_PALABRA.exec(t))) { T.push({ w: m[0], sep: t.slice(ultimo, m.index) }); ultimo = m.index + m[0].length; }
  const cola = t.slice(ultimo);
  colaTxt = cola;

  corrigeLimites(T);
  for (let i = 0; i < T.length; i++) {
    if (T[i].w.includes(' ')) continue;
    const inicio = i === 0 || /[.!?¿¡\n]\s*$/.test(T[i].sep);
    const clave = (inicio ? '^' : '') + T[i].w;
    let r = MEMO.get(clave);
    if (r === undefined) {
      r = corrigePalabra(T[i].w, inicio);
      if (MEMO.size > 8000) MEMO.clear();
      MEMO.set(clave, r);
    }
    T[i].w = r;
  }
  corrigeGramatica(T);

  t = T.map(x => x.sep + x.w).join('') + cola;
  t = mayusculas(t);
  return t.replace(/\uE000(\d+)\uE001/g, (_x, n: string) => guardados[+n]);
}

/** Carga los índices por adelantado (≈1 s). Opcional: llamarla al abrir el
 *  módulo, p. ej. `requestIdleCallback(precargarCorrector)`, para que el primer
 *  clic en «Mejorar texto» sea instantáneo. */
export function precargarCorrector(): void { init(); }

/** Alias con el nombre genérico. */
export const corregirTexto = corregirOrtografia;
